"""Shadow-mode delivery gate -- SPEC.md section 2.

  "Nothing generated by this pipeline reaches the client until it has
   run once in shadow mode (full pipeline, internal review only)."

Concretely:

  * every run is ``shadow`` unless a caller explicitly asks for
    ``live`` -- an unspecified or unrecognized mode is shadow;
  * a shadow run's report is never client-deliverable, by construction;
  * a live run's report is client-deliverable only if a full shadow run
    for this engagement has completed AND an internal reviewer has
    signed it off.

This module holds that engagement-level state -- a small JSON ledger of
shadow-run and sign-off records -- and answers the one question the
report stage asks: ``is_client_delivery_unlocked()``. The ledger stores
run ids, counts and timestamps, never report content.

It is a file for the same reason the checkpointer is SQLite: fine for
the demo, ephemeral on Render's free tier, and it moves to a DB row
alongside the app DB on the Postgres migration (docs/deployment.md).
Point it elsewhere for tests with ``SHADOW_LEDGER_PATH`` or by
constructing ``ShadowLedger`` directly.
"""

from __future__ import annotations

import json
import os
import threading
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, Optional

SHADOW = "shadow"
LIVE = "live"

_PROJECT_ROOT = Path(__file__).resolve().parents[2]
_DEFAULT_LEDGER_PATH = _PROJECT_ROOT / "knowledge_db" / "shadow_ledger.json"


def normalize_mode(value: Any) -> str:
    """Anything that is not exactly "live" (case-insensitive) is
    "shadow". Fail-safe: a blank, a typo, or None never accidentally
    produces a client-deliverable run."""
    return LIVE if str(value or "").strip().lower() == LIVE else SHADOW


def _approved(decision: Any) -> bool:
    """Only a recognized approval shape counts -- same fail-closed rule
    as app.orchestration.gates._is_signoff_approved, kept local so this
    module does not reach into that one's internals."""
    if decision == "approved":
        return True
    if isinstance(decision, dict):
        if decision.get("action") in {"approve", "approved"}:
            return True
        if decision.get("signed_off") is True or decision.get("approved") is True:
            return True
    return False


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


class ShadowSignoffError(RuntimeError):
    """Raised when a sign-off names a run that is not a recorded shadow
    run for this engagement."""


@dataclass
class ShadowLedger:
    path: Path

    def __post_init__(self) -> None:
        self.path = Path(self.path)
        self._lock = threading.Lock()

    # --- persistence -------------------------------------------------

    def _load(self) -> Dict[str, Any]:
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
        except (FileNotFoundError, json.JSONDecodeError):
            data = {}
        data.setdefault("shadow_runs", [])
        data.setdefault("signoffs", [])
        return data

    def _save(self, data: Dict[str, Any]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps(data, indent=2, sort_keys=True), encoding="utf-8")

    # --- writes ----------------------------------------------------

    def record_shadow_run(self, run_id: str, *, application_count: int) -> None:
        """Idempotent by run id -- a resumed or re-run render_report
        must not double-record."""
        if not run_id:
            return
        with self._lock:
            data = self._load()
            if any(entry["run_id"] == run_id for entry in data["shadow_runs"]):
                return
            data["shadow_runs"].append(
                {"run_id": run_id, "application_count": application_count, "completed_at": _now()}
            )
            self._save(data)

    def sign_off(self, run_id: str, *, reviewer: str, decision: Any) -> Dict[str, Any]:
        with self._lock:
            data = self._load()
            if not any(entry["run_id"] == run_id for entry in data["shadow_runs"]):
                raise ShadowSignoffError(
                    f"{run_id} is not a recorded shadow run -- a shadow run must complete before it can be signed off"
                )
            record = {
                "run_id": run_id,
                "reviewer": reviewer,
                "decision": decision,
                "approved": _approved(decision),
                "signed_off_at": _now(),
            }
            data["signoffs"].append(record)
            self._save(data)
            return record

    # --- reads ---------------------------------------------------

    def is_client_delivery_unlocked(self) -> bool:
        """True once any recorded shadow run has an approved sign-off."""
        data = self._load()
        shadow_ids = {entry["run_id"] for entry in data["shadow_runs"]}
        return any(s["run_id"] in shadow_ids and s["approved"] for s in data["signoffs"])

    def status(self) -> Dict[str, Any]:
        data = self._load()
        return {
            "client_delivery_unlocked": self.is_client_delivery_unlocked(),
            "shadow_runs": data["shadow_runs"],
            "signoffs": data["signoffs"],
        }

    # --- report stamping -------------------------------------------

    def delivery_status(self, run_mode: str) -> Dict[str, Any]:
        """The ``delivery`` block the report carries. A shadow run is
        never deliverable; a live run is deliverable only once the
        engagement is unlocked."""
        mode = normalize_mode(run_mode)
        if mode == SHADOW:
            return {
                "run_mode": SHADOW,
                "client_deliverable": False,
                "shadow_signoff_on_record": self.is_client_delivery_unlocked(),
                "reason": "Shadow run -- full pipeline, internal review only (SPEC.md section 2). "
                          "Nothing in this report may be shared with the client.",
            }
        if self.is_client_delivery_unlocked():
            return {
                "run_mode": LIVE,
                "client_deliverable": True,
                "shadow_signoff_on_record": True,
                "reason": "Live run; a signed-off shadow run is on record for this engagement.",
            }
        return {
            "run_mode": LIVE,
            "client_deliverable": False,
            "shadow_signoff_on_record": False,
            "reason": "Live run blocked from client delivery: no shadow run has been signed off for this "
                      "engagement yet (SPEC.md section 2). Run and review a shadow run first.",
        }


_default_ledger: Optional[ShadowLedger] = None
_default_lock = threading.Lock()


def default_ledger() -> ShadowLedger:
    """Process-wide ledger at ``SHADOW_LEDGER_PATH`` (or the default
    under knowledge_db/). Tests construct their own ``ShadowLedger``."""
    global _default_ledger
    with _default_lock:
        if _default_ledger is None:
            path = os.getenv("SHADOW_LEDGER_PATH") or _DEFAULT_LEDGER_PATH
            _default_ledger = ShadowLedger(Path(path))
        return _default_ledger


def reset_default_ledger() -> None:
    """Test hook -- drop the cached singleton so the next call re-reads
    the environment."""
    global _default_ledger
    with _default_lock:
        _default_ledger = None
